const DB='mission-os-alpha-01';let db;let activePage=null;const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB,1);req.onupgradeneeded=()=>{const d=req.result;d.createObjectStore('pages',{keyPath:'id'});d.createObjectStore('journal',{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function all(store){return new Promise((res,rej)=>{const r=db.transaction(store).objectStore(store).getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);});}
function put(store,value){return new Promise((res,rej)=>{const t=db.transaction(store,'readwrite');t.objectStore(store).put(value);t.oncomplete=()=>res();t.onerror=()=>rej(t.error);});}
function del(store,id){return new Promise((res,rej)=>{const t=db.transaction(store,'readwrite');t.objectStore(store).delete(id);t.oncomplete=()=>res();t.onerror=()=>rej(t.error);});}
function uid(){return crypto.randomUUID?crypto.randomUUID():String(Date.now())+Math.random();}
function show(view){$$('.view').forEach(v=>v.classList.toggle('active',v.id==='view-'+view));$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#page-heading').textContent={today:'Today',workspace:'Workspace',journal:'Journal',manage:'Manage'}[view]||view;if(view==='workspace')renderPages();if(view==='journal')renderJournal();}
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>show(b.dataset.view)));$$('[data-go]').forEach(b=>b.addEventListener('click',()=>show(b.dataset.go)));
async function renderPages(){const pages=(await all('pages')).sort((a,b)=>b.updated-a.updated);$('#pages-list').innerHTML=pages.length?pages.map(p=>'<div class="page-item" data-id="'+p.id+'">'+escapeHTML(p.title||'Untitled page')+'</div>').join(''):'<div class="empty">No pages yet. Create your first page.</div>';$$('.page-item').forEach(el=>el.onclick=()=>loadPage(el.dataset.id));}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
async function loadPage(id){const p=(await all('pages')).find(x=>x.id===id);if(!p)return;activePage=p.id;$('#page-title').value=p.title||'';$('#page-body').innerHTML=p.body||'';$('#save-status').textContent='Saved locally';}
async function savePage(){if(!activePage)activePage=uid();await put('pages',{id:activePage,title:$('#page-title').value,body:$('#page-body').innerHTML,updated:Date.now()});$('#save-status').textContent='Saved locally';renderPages();}
$('#new-page').onclick=async()=>{activePage=uid();$('#page-title').value='';$('#page-body').innerHTML='';await savePage();$('#page-title').focus();};
let saveTimer;['#page-title','#page-body'].forEach(s=>$(s).addEventListener('input',()=>{clearTimeout(saveTimer);$('#save-status').textContent='Saving…';saveTimer=setTimeout(savePage,450);}));
$$('[data-format]').forEach(b=>b.onclick=()=>{document.execCommand(b.dataset.format,false,b.dataset.value||null);$('#page-body').focus();});
$('#save-entry').onclick=async()=>{const content=$('#capture-text').value.trim();if(!content)return;await put('journal',{id:uid(),type:$('#capture-type').value,content,created:Date.now()});$('#capture-text').value='';renderJournal();};
async function renderJournal(){const entries=(await all('journal')).sort((a,b)=>b.created-a.created);$('#journal-list').innerHTML=entries.map(e=>'<article class="journal-entry"><div class="entry-meta"><span>'+escapeHTML(e.type)+' · '+new Date(e.created).toLocaleString()+'</span><button data-delete="'+e.id+'">Delete</button></div><p>'+escapeHTML(e.content)+'</p></article>').join('')||'<div class="panel empty">Your journal is empty. Capture your first thought above.</div>';$$('[data-delete]').forEach(b=>b.onclick=async()=>{await del('journal',b.dataset.delete);renderJournal();});$('#recent-activity').textContent=entries[0]?entries[0].type+': '+entries[0].content.slice(0,75):'Nothing captured yet.';}
$('#recovery-toggle').onchange=e=>{document.body.classList.toggle('recovery',e.target.checked);localStorage.setItem('mission-recovery',e.target.checked?'1':'0');};$('#recovery-toggle').checked=localStorage.getItem('mission-recovery')==='1';document.body.classList.toggle('recovery',$('#recovery-toggle').checked);
$('#export-data').onclick=async()=>{const data={pages:await all('pages'),journal:await all('journal'),exportedAt:new Date().toISOString()};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='mission-os-backup.json';a.click();URL.revokeObjectURL(a.href);};
(async()=>{try{db=await openDB();await renderPages();await renderJournal();}catch(e){console.error(e);alert('Local storage could not be opened in this browser.');}})();
if('serviceWorker'in navigator&&location.protocol.startsWith('http'))window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(console.warn));